package handlers

import (
	"bytes"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// #970 — csv and json are byte-identical to the pre-#970 handler for every
// request that does not use the new header labels. The goldens under
// testdata/export_golden were generated by THIS test, run with
// SNOWPLOW_EXPORT_GOLDEN_UPDATE=1 against the handler at 9bd5385b (main,
// before #970 touched export.go), and are compared byte for byte here: the
// status, the response headers an export sets, the body, AND the query of
// every /call re-dispatch (so the stripped-param set is pinned too). The
// unsupported-format 400 is deliberately not a golden: its message names the
// supported formats, and pdf is one now.

// goldenEnvelope exercises every cell shape the serializers handle: nested
// maps (dot-path flattening), arrays and empty maps (JSON-encoded), null,
// bools, integral and fractional floats, formula-trigger strings (CSV
// neutralization), non-ASCII text, a key that itself contains dots, and a
// row with a missing column.
const goldenEnvelope = `{"items":[
	{"name":"alpha","health":"OK","usage":{"cpu":2,"mem":1.5},"tags":["a","b"],"meta":{},"note":null,"ready":true,"labels":{"app.kubernetes.io/name":"web"}},
	{"name":"=1+1","health":"Critical, degraded","usage":{"cpu":7},"tags":[],"ready":false,"text":"Grüße — Ελληνικά — Кириллица — 東京","multi":"line one\nline \"two\""},
	{"name":"@SUM(A1)","health":"-x","usage":{"cpu":0.25},"ready":true}
]}`

type goldenCase struct {
	name   string
	target string
	paged  int // >0: serve a paginating target of this many rows at page size 2, max 2 pages
}

var goldenCases = []goldenCase{
	{name: "csv_default", target: "/export?apiVersion=templates.krateo.io/v1&resource=restactions&name=demo&namespace=ns&filename=golden"},
	{name: "csv_explicit_format", target: "/export?resource=restactions&name=demo&format=CSV&filename=golden"},
	{name: "csv_fields", target: "/export?resource=restactions&name=demo&format=csv&fields=name,%20health,usage.cpu,missing,labels.app.kubernetes.io/name,tags,meta,note,ready,text,multi&filename=golden"},
	{name: "csv_path", target: "/export?resource=restactions&name=demo&format=csv&path=.items%5B1:%5D&filename=golden"},
	{name: "json_default", target: "/export?resource=restactions&name=demo&format=json&filename=golden"},
	{name: "json_fields_ignored", target: "/export?resource=restactions&name=demo&format=json&fields=name,health&filename=golden"},
	{name: "json_path", target: "/export?resource=restactions&name=demo&format=json&path=.items%5B0%5D.usage&filename=golden.json"},
	{name: "csv_caller_window", target: "/export?resource=restactions&name=demo&format=csv&page=2&perPage=1&filename=golden", paged: 5},
	{name: "csv_truncated", target: "/export?resource=restactions&name=demo&format=csv&filename=golden", paged: 10},
	{name: "json_truncated", target: "/export?resource=restactions&name=demo&format=json&filename=golden", paged: 10},
	{name: "json_full_list", target: "/export?resource=restactions&name=demo&format=json&filename=golden", paged: 3},
	{name: "call_failure", target: "/export?resource=restactions&name=demo&format=csv&fail=1"},
}

// goldenCall serves goldenEnvelope (or, for paged cases, a window over a
// synthetic dataset) and records the query of every re-dispatch.
func goldenCall(paged int, queries *[]string) http.Handler {
	return http.HandlerFunc(func(wri http.ResponseWriter, req *http.Request) {
		*queries = append(*queries, req.URL.RawQuery)
		wri.Header().Set("Content-Type", "application/json")
		if req.URL.Query().Get("fail") != "" {
			wri.Header().Set("Content-Type", "text/html")
			wri.Header().Set("X-From-Call", "yes")
			wri.WriteHeader(http.StatusForbidden)
			_, _ = wri.Write([]byte(`{"kind":"Status","status":"Failure","code":403,"message":"forbidden"}`))
			return
		}
		if paged == 0 {
			wri.WriteHeader(http.StatusOK)
			_, _ = wri.Write([]byte(goldenEnvelope))
			return
		}
		page, _ := strconv.Atoi(req.URL.Query().Get("page"))
		perPage, _ := strconv.Atoi(req.URL.Query().Get("perPage"))
		start, end := (page-1)*perPage, page*perPage
		if start > paged {
			start = paged
		}
		if end > paged {
			end = paged
		}
		items := make([]string, 0, end-start)
		for i := start; i < end; i++ {
			items = append(items, fmt.Sprintf(`{"id":%d,"name":"row-%d","nested":{"v":%d.5}}`, i, i, i))
		}
		wri.WriteHeader(http.StatusOK)
		fmt.Fprintf(wri, `{"items":[%s]}`, strings.Join(items, ","))
	})
}

// renderGolden serializes everything a byte-identity claim covers.
func renderGolden(t *testing.T, c goldenCase) []byte {
	t.Helper()
	if c.paged > 0 {
		setExportPaging(t, 2, 2)
	}
	var queries []string
	rec := doExport(t, goldenCall(c.paged, &queries), c.target)
	var b bytes.Buffer
	fmt.Fprintf(&b, "status: %d\n", rec.Code)
	for _, h := range []string{"Content-Type", "Content-Disposition", exportTruncatedHeader, "X-Content-Type-Options", "X-From-Call"} {
		fmt.Fprintf(&b, "%s: %q\n", h, rec.Header().Get(h))
	}
	for i, q := range queries {
		fmt.Fprintf(&b, "call[%d]: %s\n", i, q)
	}
	b.WriteString("body:\n")
	b.Write(rec.Body.Bytes())
	return b.Bytes()
}

func TestExportGoldenDefaultsByteIdentical(t *testing.T) {
	update := os.Getenv("SNOWPLOW_EXPORT_GOLDEN_UPDATE") == "1"
	for _, c := range goldenCases {
		t.Run(c.name, func(t *testing.T) {
			got := renderGolden(t, c)
			path := filepath.Join("testdata", "export_golden", c.name+".golden")
			if update {
				if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
					t.Fatal(err)
				}
				if err := os.WriteFile(path, got, 0o644); err != nil {
					t.Fatal(err)
				}
				return
			}
			want, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("read golden: %v", err)
			}
			if !bytes.Equal(got, want) {
				t.Errorf("export output is not byte-identical to the pre-#970 golden %s\n--- got ---\n%s\n--- want ---\n%s", path, got, want)
			}
		})
	}
}
